#include <string>
#include <cmath>
#include <algorithm>

class Solution {
public:
    int minRotationsToDial(std::string target) {
        int curr = 0;
        int total = 0;
        for (char ch : target) {
            int dig = ch - '0';
            int diff = std::abs(curr - dig);
            total += std::min(diff, 10 - diff);
            curr = dig;
        }
        return total;
    }
};

class Solution {
    public int minRotationsToDial(String target) {
        int curr = 0;
        int total = 0;
        for (char ch : target.toCharArray()) {
            int dig = ch - '0';
            int diff = Math.abs(curr - dig);
            total += Math.min(diff, 10 - diff);
            curr = dig;
        }
        return total;
    }
}

function minRotationsToDial(target) {
    let curr = 0;
    let total = 0;
    for (const ch of target) {
        const dig = parseInt(ch, 10);
        const diff = Math.abs(curr - dig);
        total += Math.min(diff, 10 - diff);
        curr = dig;
    }
    return total;
}
